import{_ as t,o as s,c as o,a5 as r}from"./chunks/framework.CsGesDJn.js";const g=JSON.parse('{"title":"Sequence Flow — Change Password","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-5-change-password/sequence-flow.md","filePath":"feature/authentication/3-2-5-change-password/sequence-flow.md"}'),a={name:"feature/authentication/3-2-5-change-password/sequence-flow.md"};function c(i,e,d,n,l,h){return s(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="sequence-flow-—-change-password" tabindex="-1">Sequence Flow — Change Password <a class="header-anchor" href="#sequence-flow-—-change-password" aria-label="Permalink to &quot;Sequence Flow — Change Password&quot;">​</a></h1><p>&gt; Supplements <code>spec.md</code> (FR 3.2.5). This file lists each step as actor → action → system, in enough detail to draw the sequence diagram directly — it does not restate business rules (see spec.md for those).</p><h2 id="actors" tabindex="-1">Actors <a class="header-anchor" href="#actors" aria-label="Permalink to &quot;Actors&quot;">​</a></h2><ul><li><strong>Guest</strong> — actor tương tác chính trong quy trình.</li><li><strong>Client</strong> — giao diện người dùng <code>SecuritySettingsPage (UI)</code>.</li><li><strong>System</strong> — <code>AuthController</code> / <code>AuthService</code>.</li></ul><hr><h2 id="flow-a-—-luong-thuc-thi-chinh-change-password" tabindex="-1">Flow A — Luồng thực thi chính: Change Password <a class="header-anchor" href="#flow-a-—-luong-thuc-thi-chinh-change-password" aria-label="Permalink to &quot;Flow A — Luồng thực thi chính: Change Password&quot;">​</a></h2><ol><li>authservice -&gt; authservice: <code>parseToken(accessToken) -&gt; userId</code></li><li>authservice -&gt; authservice: <code>verifyPassword(request.currentPassword(), user.getPasswordHash())</code></li><li>authservice -&gt; authservice: <code>checkSamePassword(request.newPassword(), user.getPasswordHash())</code></li><li>authservice -&gt; authservice: <code>encodePassword(request.newPassword())</code></li><li>authservice -&gt; authservice: <code>updatePassword(user, newPasswordHash)</code></li><li>authservice -&gt; authservice: <code>recordAuditLog(userId, PASSWORD_RESET)</code></li><li>guest -&gt; securitysettingspage: <code>enters current password, new password &amp; clicks &quot;Update password&quot;</code></li><li>securitysettingspage -&gt; authcontroller: <code>POST /api/v1/auth/change-password (ChangePasswordRequest, headers: Bearer accessToken)</code></li><li>authcontroller --&gt; securitysettingspage: <code>401 Unauthorized (INVALID_CREDENTIALS)</code></li><li>securitysettingspage --&gt; guest: <code>show error toast (&#39;Authentication session invalid, please sign in again&#39;)</code></li><li>authcontroller -&gt;&gt; authservice: <code>changePassword(accessToken, request)</code></li><li>authservice -&gt;&gt; userrepository: <code>findById(userId)</code></li><li>userrepository --&gt; authservice: <code>Optional.empty()</code></li><li>authservice --&gt; authcontroller: <code>throw BusinessException(USER_NOT_FOUND)</code></li><li>authcontroller --&gt; securitysettingspage: <code>404 Not Found (USER_NOT_FOUND)</code></li><li>securitysettingspage --&gt; guest: <code>show error toast (&#39;User account not found&#39;)</code></li><li>userrepository --&gt; authservice: <code>user</code></li><li>authservice --&gt; authcontroller: <code>throw BusinessException(WRONG_CURRENT_PASSWORD)</code></li><li>authcontroller --&gt; securitysettingspage: <code>400 Bad Request (WRONG_CURRENT_PASSWORD)</code></li><li>securitysettingspage --&gt; guest: <code>show error inline MSG19 (&#39;Current password is incorrect.&#39;)</code></li><li>authservice --&gt; authcontroller: <code>throw BusinessException(SAME_AS_CURRENT_PASSWORD)</code></li><li>authcontroller --&gt; securitysettingspage: <code>400 Bad Request (SAME_AS_CURRENT_PASSWORD)</code></li><li>securitysettingspage --&gt; guest: <code>show error inline MSG90 (&#39;New password cannot be the same as your current password.&#39;)</code></li><li>authservice -&gt;&gt; userrepository: <code>save(user)</code></li><li>userrepository --&gt; authservice: <code>savedUser</code></li><li>authservice --&gt; authcontroller: <code>void</code></li><li>authcontroller --&gt; securitysettingspage: <code>200 OK (ApiResponse)</code></li><li>securitysettingspage --&gt; guest: <code>show success toast MSG18 (&#39;Password updated successfully.&#39;) &amp; clear form fields</code></li></ol><hr><h2 id="error-paths" tabindex="-1">Error paths <a class="header-anchor" href="#error-paths" aria-label="Permalink to &quot;Error paths&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Step</th><th>Failure condition</th><th>HTTP</th><th>ErrorCode</th></tr></thead><tbody><tr><td>Xác thực</td><td>Token thiếu, hết hạn hoặc không hợp lệ</td><td>401</td><td><code>UNAUTHORIZED</code></td></tr><tr><td>Phân quyền</td><td>Vai trò người dùng không có quyền truy cập tính năng</td><td>403</td><td><code>FORBIDDEN</code></td></tr><tr><td>Kiểm tra dữ liệu</td><td>Dữ liệu đầu vào không hợp lệ hoặc xung đột trạng thái</td><td>400</td><td><code>BAD_REQUEST</code></td></tr><tr><td>Truy vấn</td><td>Không tìm thấy bản ghi đối tượng tương ứng</td><td>404</td><td><code>NOT_FOUND</code></td></tr></tbody></table>',10)])])}const p=t(a,[["render",c]]);export{g as __pageData,p as default};
